package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// Markers of the AGENTS.md section. They differ from the CLAUDE.md/GEMINI.md
// pair (<!-- /gleann -->) so a file that holds both kinds, for example a
// CLAUDE.md symlinked to AGENTS.md, cannot cross-match.
const (
	agentsSectionStart = "<!-- gleann:agents -->"
	agentsSectionEnd   = "<!-- /gleann:agents -->"
	agentsHeading      = "## gleann: Code Intelligence"
)

// agentsFingerprints identify text generated by getAgentsMDContent. A
// marker-less section is only replaced or removed when it contains one.
var agentsFingerprints = []string{"### 1 — Before exploring source files", "gleann memory remember"}

type span struct{ start, end int }

// markerSpans returns every block that runs from startSentinel to the matching
// endSentinel. A block is accepted only when its end marker follows the start
// and no other HTML comment ("<!--") lies between them; any
// other shape is reported as a problem and nothing is returned, so callers
// leave the file alone instead of deleting user text.
func markerSpans(s, startSentinel, endSentinel string) ([]span, string) {
	var spans []span
	pos := 0
	for {
		i := strings.Index(s[pos:], startSentinel)
		if i < 0 {
			return spans, ""
		}
		i += pos
		bodyStart := i + len(startSentinel)
		j := strings.Index(s[bodyStart:], endSentinel)
		if j < 0 {
			return nil, "a start marker without its end marker " + endSentinel
		}
		j += bodyStart
		if strings.Contains(s[bodyStart:j], "<!--") {
			return nil, "another HTML comment between the start marker and the end marker " + endSentinel
		}
		spans = append(spans, span{i, j + len(endSentinel)})
		pos = j + len(endSentinel)
	}
}

// agentsWorkflowPrefix starts the last paragraph of every released variant of
// the generated AGENTS.md text: one line (v1.9 onwards) or two lines (the
// first releases, ending in "about the codebase.").
const (
	agentsWorkflowPrefix = "**Workflow:** call `memory_context` at the start of every session"
	agentsWorkflowEnd    = "important about the codebase."
)

// legacyAgentsSpan finds an AGENTS.md section written without markers. It
// starts at the line "## gleann: Code Intelligence..." and ends, in order of
// preference, at the end of the generated text's known last paragraph, at the
// earliest following "# " or "## " heading, or at a line that is exactly
// "---". found reports a heading; generated that the block holds a gleann
// fingerprint; bounded that an end was identified. Without one (a paragraph
// of the user's might follow) the caller must not replace or remove.
func legacyAgentsSpan(s string) (sp span, found, generated, bounded bool) {
	start := -1
	off := 0
	lines := strings.SplitAfter(s, "\n")
	type ln struct {
		text string
		off  int
	}
	var tail []ln
	for _, line := range lines {
		trimmed := strings.TrimRight(line, "\r\n")
		if start < 0 {
			if strings.HasPrefix(trimmed, agentsHeading) {
				start = off
			}
		}
		if start >= 0 {
			tail = append(tail, ln{trimmed, off})
		}
		off += len(line)
	}
	if start < 0 {
		return span{}, false, false, false
	}
	end := -1
	// 1. The known last paragraph, within the section (before any heading).
	for i, l := range tail {
		if i > 0 && (strings.HasPrefix(l.text, "# ") || strings.HasPrefix(l.text, "## ") || l.text == "---") {
			break
		}
		if strings.HasPrefix(l.text, agentsWorkflowPrefix) {
			for j := i; j < len(tail) && j < i+3; j++ {
				if strings.HasSuffix(tail[j].text, agentsWorkflowEnd) {
					end = tail[j].off + len(tail[j].text)
					if end < len(s) && s[end] == '\r' {
						end++
					}
					if end < len(s) && s[end] == '\n' {
						end++
					}
					break
				}
			}
			break
		}
	}
	// 2. The next heading or rule.
	if end < 0 {
		for i, l := range tail {
			if i > 0 && (strings.HasPrefix(l.text, "# ") || strings.HasPrefix(l.text, "## ") || l.text == "---") {
				end = l.off
				break
			}
		}
	}
	if end < 0 {
		return span{start, len(s)}, true, agentsGenerated(s[start:]), false
	}
	sp = span{start, end}
	return sp, true, agentsGenerated(s[start:end]), true
}

func agentsGenerated(block string) bool {
	for _, f := range agentsFingerprints {
		if strings.Contains(block, f) {
			return true
		}
	}
	return false
}

// spliceSpans replaces the first span with repl and drops the others.
func spliceSpans(s string, spans []span, repl string) string {
	var sb strings.Builder
	last := 0
	for i, sp := range spans {
		sb.WriteString(s[last:sp.start])
		if i == 0 {
			sb.WriteString(repl)
		}
		last = sp.end
	}
	sb.WriteString(s[last:])
	return sb.String()
}

func skipSymlink(warn io.Writer, path string) bool {
	sym, target, _ := isSymlink(path)
	if sym && !followSymlinkFlag {
		fmt.Fprintf(warn, "  ⚠ Skipped %s (points to symlink %s; use --follow-symlink to modify)\n", path, target)
		return true
	}
	return false
}

func appendToFile(path, content string) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = f.WriteString(content)
	return err
}

// upsertSection writes content into path, replacing every existing block from
// startSentinel to endSentinel (an older text variant is updated, never
// duplicated); without a block it appends content. A block that is not
// well-formed (see markerSpans) leaves the file untouched with a warning.
func upsertSection(info, warn io.Writer, path, content, startSentinel, endSentinel string) error {
	if skipSymlink(warn, path) {
		return nil
	}
	existing, err := os.ReadFile(path)
	if err != nil {
		return os.WriteFile(path, []byte(content), 0o644)
	}
	s := string(existing)
	spans, problem := markerSpans(s, startSentinel, endSentinel)
	if problem != "" {
		fmt.Fprintf(warn, "  ⚠ %s: found %s; an older gleann section may be present, left unchanged\n", path, problem)
		return nil
	}
	if len(spans) == 0 {
		return appendToFile(path, content)
	}
	updated := spliceSpans(s, spans, strings.Trim(content, "\n"))
	if updated == s {
		fmt.Fprintf(info, "  (already up to date in %s)\n", filepath.Base(path))
		return nil
	}
	fmt.Fprintf(info, "  (replaced the older gleann section in %s)\n", filepath.Base(path))
	return os.WriteFile(path, []byte(updated), 0o644)
}

// upsertAgentsSection is the one writer of the gleann section in AGENTS.md
// (and the files that carry the same text). Marked sections are replaced;
// a marker-less one from an older version is replaced only when it holds a
// gleann fingerprint, otherwise it is left alone with a warning.
func upsertAgentsSection(info, warn io.Writer, path, content string) error {
	if skipSymlink(warn, path) {
		return nil
	}
	existing, err := os.ReadFile(path)
	if err != nil {
		return os.WriteFile(path, []byte(strings.TrimPrefix(content, "\n")), 0o644)
	}
	s := string(existing)
	spans, problem := markerSpans(s, agentsSectionStart, agentsSectionEnd)
	if problem != "" {
		fmt.Fprintf(warn, "  ⚠ %s: found %s; left unchanged\n", path, problem)
		return nil
	}
	if len(spans) > 0 {
		updated := spliceSpans(s, spans, strings.Trim(content, "\n"))
		if updated == s {
			fmt.Fprintf(info, "  (already up to date in %s)\n", filepath.Base(path))
			return nil
		}
		fmt.Fprintf(info, "  (replaced the older gleann section in %s)\n", filepath.Base(path))
		return os.WriteFile(path, []byte(updated), 0o644)
	}
	if sp, found, generated, bounded := legacyAgentsSpan(s); found {
		if !generated {
			fmt.Fprintf(warn, "  ⚠ %s has a %q section without gleann markers that does not look generated; left unchanged\n", path, agentsHeading)
			return nil
		}
		if !bounded {
			fmt.Fprintf(warn, "  ⚠ %s has an older %q section without markers whose end cannot be told from your text; left unchanged (delete it by hand to reinstall)\n", path, agentsHeading)
			return nil
		}
		repl := strings.Trim(content, "\n") + "\n"
		if sp.end < len(s) && s[sp.end] != '\n' {
			repl += "\n"
		}
		fmt.Fprintf(info, "  (replaced the older gleann section in %s)\n", filepath.Base(path))
		return os.WriteFile(path, []byte(s[:sp.start]+repl+s[sp.end:]), 0o644)
	}
	return appendToFile(path, content)
}

// removeAgentsSection removes the gleann section from AGENTS.md, using the same
// boundaries as upsertAgentsSection. Text after the section is kept.
func removeAgentsSection(path string) error {
	if skipSymlink(os.Stdout, path) {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	s := string(data)
	spans, problem := markerSpans(s, agentsSectionStart, agentsSectionEnd)
	if problem != "" {
		fmt.Fprintf(os.Stdout, "  ⚠ %s: found %s; left unchanged\n", path, problem)
		return nil
	}
	if len(spans) == 0 {
		sp, found, generated, bounded := legacyAgentsSpan(s)
		if !found {
			return nil
		}
		if !generated {
			fmt.Fprintf(os.Stdout, "  ⚠ %s has a %q section without gleann markers that does not look generated; left unchanged\n", path, agentsHeading)
			return nil
		}
		if !bounded {
			fmt.Fprintf(os.Stdout, "  ⚠ %s has an older %q section without markers whose end cannot be told from your text; left unchanged\n", path, agentsHeading)
			return nil
		}
		spans = []span{sp}
	}
	out := spliceSpans(s, spans, "")
	return os.WriteFile(path, []byte(strings.TrimRight(out, "\n")+"\n"), 0o644)
}

// removeMarkedSection removes every well-formed block from startSentinel to
// endSentinel. A malformed block (see markerSpans) leaves the file unchanged
// with a warning.
func removeMarkedSection(path, startSentinel, endSentinel string) error {
	if skipSymlink(os.Stdout, path) {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	s := string(data)
	spans, problem := markerSpans(s, startSentinel, endSentinel)
	if problem != "" {
		fmt.Fprintf(os.Stdout, "  ⚠ %s: found %s; left unchanged\n", path, problem)
		return nil
	}
	if len(spans) == 0 {
		return nil
	}
	return os.WriteFile(path, []byte(strings.TrimRight(spliceSpans(s, spans, ""), "\n")+"\n"), 0o644)
}
